import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Menu, X, BookOpen, Users, BarChart3, User, LogOut } from 'lucide-react';
import { useState } from 'react';
import { useAuthStore } from '../store';
import { Button } from '../components/common';

export function Navbar() {
  const navigate = useNavigate();
  const { isAuthenticated, user, logout } = useAuthStore();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <nav className="bg-white shadow-sm sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <Link to="/" className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center">
              <BookOpen className="w-6 h-6 text-white" />
            </div>
            <span className="text-xl font-bold text-slate-800">LinguaFlow</span>
          </Link>
          
          <div className="hidden md:flex items-center gap-6">
            {isAuthenticated && (
              <>
                <Link to="/learn" className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors">
                  <BookOpen className="w-5 h-5" />
                  <span>学习中心</span>
                </Link>
                <Link to="/practice" className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors">
                  <BarChart3 className="w-5 h-5" />
                  <span>互动训练</span>
                </Link>
                <Link to="/community" className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors">
                  <Users className="w-5 h-5" />
                  <span>社区</span>
                </Link>
              </>
            )}
          </div>
          
          <div className="hidden md:flex items-center gap-4">
            {isAuthenticated ? (
              <>
                <Link to="/profile" className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors">
                  <User className="w-5 h-5" />
                  <span>{user?.username}</span>
                </Link>
                <button
                  onClick={handleLogout}
                  className="flex items-center gap-2 text-slate-600 hover:text-red-600 transition-colors"
                >
                  <LogOut className="w-5 h-5" />
                </button>
              </>
            ) : (
              <>
                <Link to="/login">
                  <Button variant="outline" size="sm">登录</Button>
                </Link>
                <Link to="/register">
                  <Button size="sm">注册</Button>
                </Link>
              </>
            )}
          </div>
          
          <button
            className="md:hidden p-2 text-slate-600"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>
      
      <motion.div
        initial={false}
        animate={{ height: mobileMenuOpen ? 'auto' : 0 }}
        className="md:hidden overflow-hidden bg-white border-t"
      >
        <div className="px-4 py-4 space-y-3">
          {isAuthenticated ? (
            <>
              <Link to="/learn" className="block py-2 text-slate-600">学习中心</Link>
              <Link to="/practice" className="block py-2 text-slate-600">互动训练</Link>
              <Link to="/community" className="block py-2 text-slate-600">社区</Link>
              <Link to="/profile" className="block py-2 text-slate-600">个人中心</Link>
              <button onClick={handleLogout} className="block py-2 text-red-600">退出登录</button>
            </>
          ) : (
            <>
              <Link to="/login" className="block py-2 text-slate-600">登录</Link>
              <Link to="/register" className="block py-2 text-slate-600">注册</Link>
            </>
          )}
        </div>
      </motion.div>
    </nav>
  );
}
