import { motion } from 'framer-motion';
import { Check, Circle, Play } from 'lucide-react';

interface LearningPathProps {
  lessons: { id: string; title: string; completed: boolean }[];
  onLessonClick: (lessonId: string) => void;
}

export default function LearningPath({ lessons, onLessonClick }: LearningPathProps) {
  return (
    <div className="relative py-8">
      <div className="absolute left-1/2 top-0 bottom-0 w-1 bg-slate-200 -translate-x-1/2" />
      
      <div className="relative space-y-8">
        {lessons.map((lesson, index) => {
          const isLast = index === lessons.length - 1;
          
          return (
            <motion.div
              key={lesson.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.1 }}
              className="flex items-center gap-6"
            >
              <div className={`
                relative z-10 w-12 h-12 rounded-full flex items-center justify-center
                transition-all duration-300 cursor-pointer
                ${lesson.completed 
                  ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' 
                  : 'bg-white border-2 border-slate-300 text-slate-400 hover:border-indigo-400 hover:text-indigo-600'
                }
              `}
              onClick={() => onLessonClick(lesson.id)}
              >
                {lesson.completed ? (
                  <Check className="w-6 h-6" />
                ) : (
                  lesson.id === lessons.find(l => !l.completed)?.id ? (
                    <Play className="w-5 h-5 ml-0.5" />
                  ) : (
                    <Circle className="w-5 h-5" />
                  )
                )}
              </div>
              
              <div className={`flex-1 p-4 rounded-xl transition-all duration-300 ${
                lesson.completed 
                  ? 'bg-emerald-50 border border-emerald-200' 
                  : 'bg-white border border-slate-200 hover:border-indigo-300 hover:shadow-md'
              }`}>
                <div className="flex items-center justify-between">
                  <h4 className={`font-medium ${
                    lesson.completed ? 'text-emerald-700' : 'text-slate-800'
                  }`}>
                    {lesson.title}
                  </h4>
                  {lesson.completed && (
                    <span className="text-xs text-emerald-600 font-medium">已完成</span>
                  )}
                </div>
              </div>
              
              {!isLast && (
                <div className={`
                  absolute left-6 w-0.5 h-8 -top-8
                  ${lesson.completed ? 'bg-emerald-300' : 'bg-slate-200'}
                `} 
                style={{ transform: 'translateX(21px)' }}
                />
              )}
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}
