import { useState } from 'react';
import { motion } from 'framer-motion';
import { TrendingUp, Clock, Plus } from 'lucide-react';
import { Button, Card, Badge } from '../common';
import PostCard from './PostCard';
import { CommunityPost } from '../../data/types';

interface PostListProps {
  posts: CommunityPost[];
  onNewPost?: () => void;
}

const popularTags = ['学习打卡', '日语', '英语', '韩语', '学习方法', 'N3备考', 'TOPIK'];

export default function PostList({ posts, onNewPost }: PostListProps) {
  const [activeTab, setActiveTab] = useState<'trending' | 'recent'>('trending');

  return (
    <div className="space-y-6">
      <Card>
        <Card.Body className="p-4">
          <div className="flex flex-wrap gap-2">
            {popularTags.map((tag) => (
              <Badge 
                key={tag} 
                variant="default"
                className="cursor-pointer hover:bg-indigo-100 hover:text-indigo-700 transition-colors"
              >
                #{tag}
              </Badge>
            ))}
          </div>
        </Card.Body>
      </Card>
      
      <div className="flex items-center gap-4">
        <button
          onClick={() => setActiveTab('trending')}
          className={`
            flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all
            ${activeTab === 'trending' 
              ? 'bg-indigo-100 text-indigo-700' 
              : 'text-slate-600 hover:bg-slate-100'
            }
          `}
        >
          <TrendingUp className="w-4 h-4" />
          热门
        </button>
        <button
          onClick={() => setActiveTab('recent')}
          className={`
            flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all
            ${activeTab === 'recent' 
              ? 'bg-indigo-100 text-indigo-700' 
              : 'text-slate-600 hover:bg-slate-100'
            }
          `}
        >
          <Clock className="w-4 h-4" />
          最新
        </button>
        
        <div className="ml-auto">
          <Button size="sm" className="flex items-center gap-2" onClick={onNewPost}>
            <Plus className="w-4 h-4" />
            发布帖子
          </Button>
        </div>
      </div>
      
      <div className="space-y-4">
        {posts.map((post, index) => (
          <motion.div
            key={post.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
          >
            <PostCard post={post} />
          </motion.div>
        ))}
      </div>
    </div>
  );
}
