import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, BookOpen } from 'lucide-react';
import { Navbar } from './Navbar';
import { FlashCard } from '../components/practice';
import { Card, Button, ProgressBar } from '../components/common';
import { flashcards as flashCards } from '../data/mockData';
import { useLearningStore } from '../store';

export function FlashcardPage() {
  const navigate = useNavigate();
  const { currentLanguage, flashcardIndex, nextFlashcard, resetFlashcards } = useLearningStore();
  const [knownCards, setKnownCards] = useState<string[]>([]);
  const [unknownCards, setUnknownCards] = useState<string[]>([]);

  const cards = flashCards[currentLanguage] || flashCards['en'];
  const totalCards = cards.length;
  const progress = ((flashcardIndex + 1) / totalCards) * 100;
  const isCompleted = flashcardIndex >= totalCards;

  const handleKnow = () => {
    const currentCard = cards[flashcardIndex];
    if (!knownCards.includes(currentCard.id)) {
      setKnownCards([...knownCards, currentCard.id]);
    }
  };

  const handleDontKnow = () => {
    const currentCard = cards[flashcardIndex];
    if (!unknownCards.includes(currentCard.id)) {
      setUnknownCards([...unknownCards, currentCard.id]);
    }
  };

  const handleReset = () => {
    resetFlashcards();
    setKnownCards([]);
    setUnknownCards([]);
  };

  if (isCompleted) {
    const accuracy = Math.round((knownCards.length / totalCards) * 100);
    
    return (
      <div className="min-h-screen bg-slate-50">
        <Navbar />
        <div className="max-w-2xl mx-auto px-4 py-12">
          <motion.div
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="text-center"
          >
            <div className="text-8xl mb-6">🎉</div>
            <h1 className="text-3xl font-bold text-slate-800 mb-4">
              练习完成！
            </h1>
            <p className="text-xl text-slate-600 mb-8">
              你认识了 {knownCards.length} / {totalCards} 个单词
            </p>
            
            <Card className="p-8 mb-8">
              <div className="flex justify-around mb-6">
                <div className="text-center">
                  <div className="text-4xl font-bold text-emerald-600">{knownCards.length}</div>
                  <div className="text-sm text-slate-500">已掌握</div>
                </div>
                <div className="text-center">
                  <div className="text-4xl font-bold text-amber-600">{accuracy}%</div>
                  <div className="text-sm text-slate-500">正确率</div>
                </div>
                <div className="text-center">
                  <div className="text-4xl font-bold text-red-600">{unknownCards.length}</div>
                  <div className="text-sm text-slate-500">需复习</div>
                </div>
              </div>
            </Card>
            
            <div className="flex gap-4 justify-center">
              <Button variant="outline" onClick={handleReset}>
                再练一次
              </Button>
              <Button onClick={() => navigate('/practice')}>
                返回训练中心
              </Button>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => navigate('/practice')}
            className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-6 h-6 text-slate-600" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-emerald-400 to-teal-500 rounded-xl flex items-center justify-center">
              <BookOpen className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800">单词记忆</h1>
              <p className="text-sm text-slate-500">翻转卡片学习单词</p>
            </div>
          </div>
        </div>
        
        <Card className="p-6 mb-6">
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-medium text-slate-600">
              学习进度
            </span>
            <span className="text-sm font-medium text-indigo-600">
              {Math.round(progress)}%
            </span>
          </div>
          <ProgressBar value={progress} size="md" />
        </Card>
        
        <motion.div
          key={flashcardIndex}
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -50 }}
        >
          <FlashCard
            cards={cards}
            currentIndex={flashcardIndex}
            onNext={nextFlashcard}
            onPrev={() => {}}
            onKnow={handleKnow}
            onDontKnow={handleDontKnow}
          />
        </motion.div>
        
        <div className="mt-6 flex justify-center gap-8">
          <div className="text-center">
            <div className="text-2xl font-bold text-emerald-600">{knownCards.length}</div>
            <div className="text-sm text-slate-500">认识</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-red-600">{unknownCards.length}</div>
            <div className="text-sm text-slate-500">不认识</div>
          </div>
        </div>
      </div>
    </div>
  );
}
