import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Play, BookOpen, FileText, Mic, Headphones, CheckCircle, ChevronLeft, ChevronRight } from 'lucide-react';
import { Card, Button, Badge } from '../components/common';
import { courses } from '../data/mockData';
import { useLearningStore } from '../store';
import { useState } from 'react';

export function LessonDetailPage() {
  const { courseId, lessonId } = useParams<{ courseId: string; lessonId: string }>();
  const navigate = useNavigate();
  const { completeLesson } = useLearningStore();
  const [currentExercise, setCurrentExercise] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [score, setScore] = useState(0);
  
  const course = courses.find(c => c.id === courseId);
  const lesson = course?.lessons.find(l => l.id === lessonId);
  
  if (!course || !lesson) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-purple-50 flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-slate-800 mb-4">课时未找到</h2>
          <Button onClick={() => navigate('/learn')}>返回学习中心</Button>
        </div>
      </div>
    );
  }
  
  const currentLessonIndex = course.lessons.findIndex(l => l.id === lessonId);
  const prevLesson = currentLessonIndex > 0 ? course.lessons[currentLessonIndex - 1] : null;
  const nextLesson = currentLessonIndex < course.lessons.length - 1 ? course.lessons[currentLessonIndex + 1] : null;
  
  const lessonTypeIcons: Record<string, any> = {
    vocabulary: BookOpen,
    grammar: FileText,
    speaking: Mic,
    listening: Headphones,
  };
  
  const TypeIcon = lessonTypeIcons[lesson.type] || BookOpen;
  
  const handleCompleteLesson = () => {
    completeLesson(course.id, lesson.id);
    if (nextLesson) {
      navigate(`/lesson/${course.id}/${nextLesson.id}`);
    } else {
      navigate(`/course/${course.id}`);
    }
  };
  
  const handleAnswerSelect = (answer: string) => {
    if (showResult) return;
    setSelectedAnswer(answer);
  };
  
  const handleCheckAnswer = () => {
    if (!selectedAnswer || !lesson.exercises) return;
    setShowResult(true);
    if (selectedAnswer === lesson.exercises[currentExercise].correctAnswer) {
      setScore(score + 1);
    }
  };
  
  const handleNextExercise = () => {
    if (!lesson.exercises) return;
    if (currentExercise < lesson.exercises.length - 1) {
      setCurrentExercise(currentExercise + 1);
      setSelectedAnswer(null);
      setShowResult(false);
    }
  };
  
  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-purple-50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <button
          onClick={() => navigate(`/course/${course.id}`)}
          className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors mb-6"
        >
          <ArrowLeft className="w-5 h-5" />
          <span>返回课程详情</span>
        </button>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          {lesson.thumbnail && (
            <div className="relative h-80 rounded-2xl overflow-hidden mb-8">
              <img
                src={lesson.thumbnail}
                alt={lesson.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/30 to-transparent" />
              <button className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-20 h-20 bg-white/90 rounded-full flex items-center justify-center hover:bg-white transition-colors shadow-lg">
                <Play className="w-8 h-8 text-indigo-600 ml-1" />
              </button>
              <div className="absolute bottom-0 left-0 right-0 p-8">
                <div className="flex items-center gap-3 mb-3">
                  <Badge variant="primary">
                    <TypeIcon className="w-4 h-4 mr-1" />
                    {lesson.type === 'vocabulary' ? '词汇' : lesson.type === 'grammar' ? '语法' : lesson.type === 'speaking' ? '口语' : '听力'}
                  </Badge>
                  <span className="text-white/80 text-sm">第 {currentLessonIndex + 1} / {course.lessons.length} 课时</span>
                </div>
                <h1 className="text-3xl font-bold text-white mb-2">{lesson.title}</h1>
                {lesson.description && (
                  <p className="text-white/90 text-lg max-w-2xl">{lesson.description}</p>
                )}
              </div>
            </div>
          )}
          
          {!lesson.thumbnail && (
            <div className="bg-white rounded-2xl p-8 mb-8 shadow-sm">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl flex items-center justify-center">
                  <TypeIcon className="w-8 h-8 text-white" />
                </div>
                <div>
                  <div className="flex items-center gap-3 mb-2">
                    <Badge variant="primary">
                      {lesson.type === 'vocabulary' ? '词汇' : lesson.type === 'grammar' ? '语法' : lesson.type === 'speaking' ? '口语' : '听力'}
                    </Badge>
                    <span className="text-slate-500 text-sm">第 {currentLessonIndex + 1} / {course.lessons.length} 课时</span>
                  </div>
                  <h1 className="text-2xl font-bold text-slate-800">{lesson.title}</h1>
                </div>
              </div>
              {lesson.description && (
                <p className="text-slate-600 text-lg">{lesson.description}</p>
              )}
            </div>
          )}
          
          <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              {lesson.content?.introduction && (
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-100 rounded-lg flex items-center justify-center">
                      <BookOpen className="w-5 h-5 text-indigo-600" />
                    </div>
                    课程介绍
                  </h2>
                  <p className="text-slate-600 leading-relaxed">
                    {lesson.content.introduction}
                  </p>
                </Card>
              )}
              
              {lesson.content?.keyPoints && lesson.content.keyPoints.length > 0 && (
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                    <div className="w-8 h-8 bg-emerald-100 rounded-lg flex items-center justify-center">
                      <CheckCircle className="w-5 h-5 text-emerald-600" />
                    </div>
                    核心要点
                  </h2>
                  <div className="grid gap-3">
                    {lesson.content.keyPoints.map((point, index) => (
                      <div key={index} className="flex items-start gap-3 p-3 bg-emerald-50 rounded-lg">
                        <div className="w-6 h-6 bg-emerald-500 rounded-full flex items-center justify-center text-white text-sm font-bold flex-shrink-0">
                          {index + 1}
                        </div>
                        <p className="text-slate-700">{point}</p>
                      </div>
                    ))}
                  </div>
                </Card>
              )}
              
              {lesson.content?.examples && lesson.content.examples.length > 0 && (
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                    <div className="w-8 h-8 bg-amber-100 rounded-lg flex items-center justify-center">
                      <FileText className="w-5 h-5 text-amber-600" />
                    </div>
                    示例对话
                  </h2>
                  <div className="space-y-4">
                    {lesson.content.examples.map((example, index) => (
                      <div 
                        key={index} 
                        className={`p-4 rounded-lg ${
                          example.startsWith('A:') 
                            ? 'bg-blue-50 border-l-4 border-blue-500' 
                            : example.startsWith('B:') 
                            ? 'bg-purple-50 border-l-4 border-purple-500'
                            : 'bg-slate-50'
                        }`}
                      >
                        <p className="text-slate-700 font-medium">{example}</p>
                      </div>
                    ))}
                  </div>
                </Card>
              )}
              
              {lesson.content?.images && lesson.content.images.length > 0 && (
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                    <div className="w-8 h-8 bg-pink-100 rounded-lg flex items-center justify-center">
                      <FileText className="w-5 h-5 text-pink-600" />
                    </div>
                    相关图片
                  </h2>
                  <div className="grid grid-cols-2 gap-4">
                    {lesson.content.images.map((image, index) => (
                      <img
                        key={index}
                        src={image}
                        alt={`相关图片 ${index + 1}`}
                        className="w-full h-48 object-cover rounded-lg"
                      />
                    ))}
                  </div>
                </Card>
              )}
              
              {lesson.exercises && lesson.exercises.length > 0 && (
                <Card className="p-6">
                  <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-100 rounded-lg flex items-center justify-center">
                      <CheckCircle className="w-5 h-5 text-indigo-600" />
                    </div>
                    随堂练习
                  </h2>
                  <div className="space-y-4">
                    <div className="text-sm text-slate-500 mb-4">
                      题目 {currentExercise + 1} / {lesson.exercises.length}
                    </div>
                    <p className="text-lg text-slate-800 font-medium mb-4">
                      {lesson.exercises[currentExercise].question}
                    </p>
                    <div className="space-y-3">
                      {lesson.exercises[currentExercise].options?.map((option, index) => {
                        const isSelected = selectedAnswer === option;
                        const isCorrect = option === lesson.exercises[currentExercise].correctAnswer;
                        let className = 'p-4 rounded-lg border-2 cursor-pointer transition-all ';
                        
                        if (showResult) {
                          if (isCorrect) {
                            className += 'bg-emerald-50 border-emerald-500';
                          } else if (isSelected && !isCorrect) {
                            className += 'bg-red-50 border-red-500';
                          } else {
                            className += 'bg-slate-50 border-slate-200 opacity-60';
                          }
                        } else {
                          className += isSelected 
                            ? 'bg-indigo-50 border-indigo-500' 
                            : 'bg-slate-50 border-slate-200 hover:border-indigo-300';
                        }
                        
                        return (
                          <div
                            key={index}
                            className={className}
                            onClick={() => handleAnswerSelect(option)}
                          >
                            <div className="flex items-center gap-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                                showResult 
                                  ? isCorrect 
                                    ? 'bg-emerald-500 text-white' 
                                    : isSelected 
                                    ? 'bg-red-500 text-white'
                                    : 'bg-slate-300 text-slate-600'
                                  : isSelected 
                                  ? 'bg-indigo-500 text-white' 
                                  : 'bg-slate-200 text-slate-600'
                              }`}>
                                {String.fromCharCode(65 + index)}
                              </div>
                              <span className="text-slate-700">{option}</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                    
                    {showResult && (
                      <div className="mt-4 p-4 bg-indigo-50 rounded-lg">
                        <p className="text-indigo-800 font-medium">
                          {selectedAnswer === lesson.exercises[currentExercise].correctAnswer 
                            ? '✓ 回答正确！' 
                            : `✗ 回答错误。正确答案是：${lesson.exercises[currentExercise].correctAnswer}`}
                        </p>
                      </div>
                    )}
                    
                    <div className="flex gap-3 mt-4">
                      {!showResult ? (
                        <Button 
                          className="flex-1"
                          onClick={handleCheckAnswer}
                          disabled={!selectedAnswer}
                        >
                          检查答案
                        </Button>
                      ) : currentExercise < lesson.exercises.length - 1 ? (
                        <Button className="flex-1" onClick={handleNextExercise}>
                          下一题
                        </Button>
                      ) : (
                        <div className="flex-1 text-center p-4 bg-emerald-100 rounded-lg">
                          <p className="text-emerald-800 font-bold text-lg">
                            练习完成！得分：{score} / {lesson.exercises.length}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </Card>
              )}
            </div>
            
            <div className="space-y-6">
              <Card className="p-6">
                <h3 className="font-semibold text-slate-800 mb-4">课时导航</h3>
                <div className="flex items-center justify-between mb-4">
                  <button
                    onClick={() => prevLesson && navigate(`/lesson/${course.id}/${prevLesson.id}`)}
                    disabled={!prevLesson}
                    className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-colors ${
                      prevLesson 
                        ? 'bg-slate-100 hover:bg-slate-200 text-slate-700' 
                        : 'bg-slate-50 text-slate-300 cursor-not-allowed'
                    }`}
                  >
                    <ChevronLeft className="w-4 h-4" />
                    上一课
                  </button>
                  <button
                    onClick={() => nextLesson && navigate(`/lesson/${course.id}/${nextLesson.id}`)}
                    disabled={!nextLesson}
                    className={`flex items-center gap-2 px-3 py-2 rounded-lg transition-colors ${
                      nextLesson 
                        ? 'bg-slate-100 hover:bg-slate-200 text-slate-700' 
                        : 'bg-slate-50 text-slate-300 cursor-not-allowed'
                    }`}
                  >
                    下一课
                    <ChevronRight className="w-4 h-4" />
                  </button>
                </div>
                
                <div className="space-y-2">
                  {course.lessons.map((l, index) => {
                    const isCurrentLesson = l.id === lessonId;
                    const LessonIcon = lessonTypeIcons[l.type] || BookOpen;
                    
                    return (
                      <div
                        key={l.id}
                        onClick={() => navigate(`/lesson/${course.id}/${l.id}`)}
                        className={`p-3 rounded-lg cursor-pointer transition-all ${
                          isCurrentLesson 
                            ? 'bg-indigo-50 border-2 border-indigo-500' 
                            : 'hover:bg-slate-50 border-2 border-transparent'
                        }`}
                      >
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                            isCurrentLesson ? 'bg-indigo-500' : 'bg-slate-200'
                          }`}>
                            <LessonIcon className={`w-4 h-4 ${isCurrentLesson ? 'text-white' : 'text-slate-600'}`} />
                          </div>
                          <div className="flex-1">
                            <div className="text-sm font-medium text-slate-800">
                              {index + 1}. {l.title}
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </Card>
              
              <Card className="p-6 bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-0">
                <h3 className="font-semibold mb-2">💡 学习小贴士</h3>
                <p className="text-sm text-white/90">
                  建议每天坚持学习30分钟，保持学习的连续性。遇到不懂的地方可以多看几遍课程内容！
                </p>
              </Card>
              
              <Button 
                className="w-full flex items-center justify-center gap-2"
                onClick={handleCompleteLesson}
              >
                <CheckCircle className="w-5 h-5" />
                {nextLesson ? '完成并学习下一课' : '完成课程'}
              </Button>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}
