import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { BookOpen, Pen, Mic, Headphones, ArrowRight } from 'lucide-react';
import { Navbar } from './Navbar';
import { Card } from '../components/common';

export function PracticePage() {
  const navigate = useNavigate();
  const [selectedModule, setSelectedModule] = useState<string | null>(null);

  const modules = [
    {
      id: 'flashcard',
      title: '单词记忆',
      description: '通过闪卡记忆单词，支持翻转查看释义',
      icon: BookOpen,
      color: 'from-emerald-400 to-teal-500',
      bgColor: 'bg-emerald-50',
      borderColor: 'border-emerald-200',
      lessons: 120,
      path: '/practice/flashcards',
    },
    {
      id: 'grammar',
      title: '语法练习',
      description: '多种题型练习，巩固语法知识',
      icon: Pen,
      color: 'from-purple-400 to-indigo-500',
      bgColor: 'bg-purple-50',
      borderColor: 'border-purple-200',
      lessons: 85,
      path: '/practice/grammar',
    },
    {
      id: 'speaking',
      title: '口语跟读',
      description: '录音对比练习，提升口语发音',
      icon: Mic,
      color: 'from-pink-400 to-rose-500',
      bgColor: 'bg-pink-50',
      borderColor: 'border-pink-200',
      lessons: 60,
      path: '/practice/speaking',
    },
    {
      id: 'listening',
      title: '听力训练',
      description: '听写练习，提高听力理解能力',
      icon: Headphones,
      color: 'from-amber-400 to-orange-500',
      bgColor: 'bg-amber-50',
      borderColor: 'border-amber-200',
      lessons: 90,
      path: '/practice/listening',
    },
  ];

  const handleModuleClick = (module: typeof modules[0]) => {
    setSelectedModule(module.id);
    setTimeout(() => {
      navigate(module.path);
    }, 300);
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-8"
        >
          <h1 className="text-3xl font-bold text-slate-800 mb-2">互动训练</h1>
          <p className="text-slate-600">选择训练模块，开始你的学习之旅</p>
        </motion.div>
        
        <div className="grid md:grid-cols-2 gap-6">
          {modules.map((module, index) => {
            const Icon = module.icon;
            const isSelected = selectedModule === module.id;
            
            return (
              <motion.div
                key={module.id}
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.1 }}
                onClick={() => handleModuleClick(module)}
                className={`
                  relative p-6 rounded-2xl cursor-pointer overflow-hidden
                  transition-all duration-300
                  ${isSelected ? 'scale-95 opacity-50' : 'hover:scale-102'}
                `}
              >
                <div className={`
                  absolute inset-0 ${module.bgColor} border-2 ${module.borderColor} rounded-2xl
                  ${isSelected ? '' : 'hover:shadow-lg'}
                `} />
                
                <div className="relative z-10 flex items-start gap-5">
                  <div className={`
                    w-16 h-16 rounded-2xl bg-gradient-to-br ${module.color}
                    flex items-center justify-center shadow-lg
                  `}>
                    <Icon className="w-8 h-8 text-white" />
                  </div>
                  
                  <div className="flex-1">
                    <h3 className="text-xl font-bold text-slate-800 mb-2">
                      {module.title}
                    </h3>
                    <p className="text-slate-600 mb-4">
                      {module.description}
                    </p>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-slate-500">
                        {module.lessons} 个练习
                      </span>
                      <div className={`
                        w-8 h-8 rounded-full bg-gradient-to-br ${module.color}
                        flex items-center justify-center
                        transform transition-transform group-hover:translate-x-1
                      `}>
                        <ArrowRight className="w-4 h-4 text-white" />
                      </div>
                    </div>
                  </div>
                </div>
                
                {!isSelected && (
                  <div className={`
                    absolute bottom-0 left-0 right-0 h-1
                    bg-gradient-to-r ${module.color}
                    transform scale-x-0 hover:scale-x-100 transition-transform origin-left
                  `} />
                )}
              </motion.div>
            );
          })}
        </div>
        
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="mt-12"
        >
          <Card className="p-8 bg-gradient-to-r from-indigo-100 to-purple-100 border border-indigo-200">
            <div className="flex items-center gap-6">
              <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-2xl flex items-center justify-center">
                <span className="text-3xl">💡</span>
              </div>
              <div className="flex-1">
                <h3 className="text-lg font-bold text-slate-800 mb-2">
                  学习小贴士
                </h3>
                <p className="text-slate-600">
                  建议每天完成不同模块的练习，这样可以帮助你更全面地提升语言能力。
                  坚持学习，你一定会看到明显的进步！
                </p>
              </div>
            </div>
          </Card>
        </motion.div>
      </div>
    </div>
  );
}
