import { motion } from 'framer-motion';
import { Star, Flame, Clock, Trophy, BookOpen, Zap } from 'lucide-react';
import { Card, ProgressRing } from '../common';
import { Achievement } from '../../data/types';

interface AchievementGridProps {
  achievements: Achievement[];
  earnedAchievements: string[];
}

export default function AchievementGrid({ achievements, earnedAchievements }: AchievementGridProps) {
  const iconMap: Record<string, any> = {
    star: Star,
    flame: Flame,
    clock: Clock,
    trophy: Trophy,
    book: BookOpen,
    zap: Zap,
  };

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
      {achievements.map((achievement, index) => {
        const Icon = iconMap[achievement.icon] || Star;
        const isEarned = earnedAchievements.includes(achievement.id);
        
        return (
          <motion.div
            key={achievement.id}
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: index * 0.1 }}
          >
            <Card 
              className={`
                text-center p-4 transition-all
                ${isEarned 
                  ? 'bg-gradient-to-br from-amber-50 to-orange-50 border-2 border-amber-300' 
                  : 'opacity-60'
                }
              `}
            >
              <div className={`
                w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-3
                ${isEarned 
                  ? 'bg-gradient-to-br from-amber-400 to-orange-400 shadow-lg shadow-amber-200' 
                  : 'bg-slate-200'
                }
              `}>
                <Icon className={`w-8 h-8 ${isEarned ? 'text-white' : 'text-slate-400'}`} />
              </div>
              
              <h4 className={`font-semibold mb-1 ${isEarned ? 'text-amber-800' : 'text-slate-500'}`}>
                {achievement.title}
              </h4>
              
              <p className="text-xs text-slate-500 mb-2 line-clamp-2">
                {achievement.description}
              </p>
              
              <div className={`
                inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium
                ${isEarned ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}
              `}>
                +{achievement.reward} 积分
              </div>
            </Card>
          </motion.div>
        );
      })}
    </div>
  );
}
