import { Users, Clock, Star, Play } from 'lucide-react';
import { Card, Badge, Button } from '../common';
import { Course } from '../../data/types';

interface CourseCardProps {
  course: Course;
  onClick: () => void;
}

export default function CourseCard({ course, onClick }: CourseCardProps) {
  const levelConfig = {
    beginner: { label: '初级', color: 'bg-emerald-100 text-emerald-700' },
    intermediate: { label: '中级', color: 'bg-amber-100 text-amber-700' },
    advanced: { label: '高级', color: 'bg-red-100 text-red-700' },
  };

  const level = levelConfig[course.level];

  return (
    <Card hover onClick={onClick} className="group">
      <div className="relative h-44 overflow-hidden rounded-t-2xl">
        <img
          src={course.coverImage}
          alt={course.title}
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent" />
        
        <div className="absolute top-3 left-3">
          <span className={`px-2.5 py-1 text-xs font-medium rounded-full ${level.color}`}>
            {level.label}
          </span>
        </div>
        
        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
          <div className="w-14 h-14 rounded-full bg-white/90 flex items-center justify-center shadow-lg">
            <Play className="w-6 h-6 text-indigo-600 ml-1" />
          </div>
        </div>
      </div>
      
      <Card.Body className="p-5">
        <h3 className="text-lg font-bold text-slate-800 mb-2 line-clamp-1">
          {course.title}
        </h3>
        <p className="text-slate-600 text-sm mb-4 line-clamp-2 h-10">
          {course.description}
        </p>
        
        <div className="flex items-center justify-between text-sm text-slate-500 mb-4">
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <Users className="w-4 h-4" />
              {course.studentsCount > 1000 
                ? `${(course.studentsCount / 1000).toFixed(1)}k` 
                : course.studentsCount}
            </span>
            <span className="flex items-center gap-1">
              <Clock className="w-4 h-4" />
              {course.duration}
            </span>
          </div>
          <span className="flex items-center gap-0.5">
            <Star className="w-4 h-4 text-amber-400 fill-amber-400" />
            <span className="font-medium">{course.rating}</span>
          </span>
        </div>
        
        <Button className="w-full" size="sm">
          开始学习
        </Button>
      </Card.Body>
    </Card>
  );
}
