import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Filter, Search, BookOpen, TrendingUp } from 'lucide-react';
import { Navbar } from './Navbar';
import { CourseCard } from '../components/learning';
import { Card, Button, Input, Badge } from '../components/common';
import { courses } from '../data/mockData';
import { useLearningStore } from '../store';

export function LearningPage() {
  const navigate = useNavigate();
  const { currentLanguage, setLanguage } = useLearningStore();
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLevel, setSelectedLevel] = useState<string>('all');

  const filteredCourses = courses.filter(course => {
    const matchesLanguage = course.language === currentLanguage;
    const matchesLevel = selectedLevel === 'all' || course.level === selectedLevel;
    const matchesSearch = course.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         course.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesLanguage && matchesLevel && matchesSearch;
  });

  const handleCourseClick = (courseId: string) => {
    navigate(`/course/${courseId}`);
  };

  const languageLabels = {
    en: { name: '英语', flag: '🇬🇧', color: 'from-blue-500 to-cyan-500' },
    ja: { name: '日语', flag: '🇯🇵', color: 'from-pink-500 to-rose-500' },
    ko: { name: '韩语', flag: '🇰🇷', color: 'from-purple-500 to-indigo-500' },
  };

  const currentLang = languageLabels[currentLanguage as keyof typeof languageLabels];

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <div className="flex items-center gap-3 mb-4">
              <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${currentLang.color} flex items-center justify-center text-2xl`}>
                {currentLang.flag}
              </div>
              <div>
                <h1 className="text-2xl font-bold text-slate-800">{currentLang.name}学习中心</h1>
                <p className="text-slate-600">发现适合你的课程，开始学习之旅</p>
              </div>
            </div>
          </motion.div>
        </div>
        
        <div className="flex flex-col lg:flex-row gap-6 mb-8">
          <Card className="lg:w-64 flex-shrink-0">
            <Card.Body className="p-4">
              <div className="mb-6">
                <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                  <BookOpen className="w-4 h-4" />
                  学习语言
                </h3>
                <div className="space-y-2">
                  {Object.entries(languageLabels).map(([key, lang]) => (
                    <button
                      key={key}
                      onClick={() => setLanguage(key)}
                      className={`
                        w-full flex items-center gap-3 p-3 rounded-lg transition-all
                        ${currentLanguage === key 
                          ? 'bg-indigo-100 text-indigo-700' 
                          : 'hover:bg-slate-100 text-slate-600'
                        }
                      `}
                    >
                      <span className="text-xl">{lang.flag}</span>
                      <span className="font-medium">{lang.name}</span>
                    </button>
                  ))}
                </div>
              </div>
              
              <div>
                <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                  <Filter className="w-4 h-4" />
                  课程难度
                </h3>
                <div className="space-y-2">
                  {[
                    { value: 'all', label: '全部', count: courses.filter(c => c.language === currentLanguage).length },
                    { value: 'beginner', label: '初级', count: courses.filter(c => c.language === currentLanguage && c.level === 'beginner').length },
                    { value: 'intermediate', label: '中级', count: courses.filter(c => c.language === currentLanguage && c.level === 'intermediate').length },
                    { value: 'advanced', label: '高级', count: courses.filter(c => c.language === currentLanguage && c.level === 'advanced').length },
                  ].map((level) => (
                    <button
                      key={level.value}
                      onClick={() => setSelectedLevel(level.value)}
                      className={`
                        w-full flex items-center justify-between p-3 rounded-lg transition-all
                        ${selectedLevel === level.value 
                          ? 'bg-indigo-100 text-indigo-700' 
                          : 'hover:bg-slate-100 text-slate-600'
                        }
                      `}
                    >
                      <span className="font-medium">{level.label}</span>
                      <Badge variant="default" size="sm">{level.count}</Badge>
                    </button>
                  ))}
                </div>
              </div>
            </Card.Body>
          </Card>
          
          <div className="flex-1">
            <div className="mb-6">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="搜索课程..."
                  className="w-full pl-12 pr-4 py-3 border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 outline-none transition-all"
                />
              </div>
            </div>
            
            <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-6">
              {filteredCourses.map((course, index) => (
                <motion.div
                  key={course.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <CourseCard 
                    course={course} 
                    onClick={() => handleCourseClick(course.id)}
                  />
                </motion.div>
              ))}
            </div>
            
            {filteredCourses.length === 0 && (
              <Card className="p-12 text-center">
                <TrendingUp className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-slate-700 mb-2">暂无相关课程</h3>
                <p className="text-slate-500">尝试调整筛选条件或搜索其他关键词</p>
              </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
