import { useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { Play, Pause, RotateCcw, CheckCircle, Volume2 } from 'lucide-react';
import { Button, Card, Input } from '../common';

interface ListeningPlayerProps {
  audioText: string;
  audioUrl?: string;
}

export default function ListeningPlayer({ audioText, audioUrl }: ListeningPlayerProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(30);
  const [userAnswer, setUserAnswer] = useState('');
  const [isChecked, setIsChecked] = useState(false);
  const [showResult, setShowResult] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const handlePlayPause = () => {
    if (!audioUrl) return;
    
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleReplay = () => {
    if (audioRef.current) {
      audioRef.current.currentTime = 0;
      audioRef.current.play();
      setIsPlaying(true);
    }
  };

  const handleCheck = () => {
    setIsChecked(true);
    setShowResult(true);
  };

  const getSimilarity = () => {
    const original = audioText.toLowerCase().split(/\s+/);
    const answer = userAnswer.toLowerCase().split(/\s+/);
    
    let matchCount = 0;
    original.forEach(word => {
      if (answer.includes(word)) matchCount++;
    });
    
    return Math.round((matchCount / original.length) * 100);
  };

  return (
    <Card className="max-w-2xl mx-auto">
      <Card.Body className="p-8">
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-50 rounded-full text-indigo-600 text-sm mb-4">
            <Volume2 className="w-4 h-4" />
            <span>听力练习</span>
          </div>
          <h3 className="text-xl font-semibold text-slate-800 mb-6">
            听音频并填写听到的内容
          </h3>
          
          <div className={`
            p-6 rounded-xl mb-6
            ${!showResult ? 'bg-slate-100' : 'bg-emerald-50 border border-emerald-200'}
          `}>
            {showResult ? (
              <div className="space-y-4">
                <div>
                  <div className="text-sm text-emerald-600 font-medium mb-1">正确答案</div>
                  <div className="text-lg text-emerald-800">{audioText}</div>
                </div>
                <div className="border-t border-emerald-200 pt-4">
                  <div className="text-sm text-slate-600 font-medium mb-1">你的答案</div>
                  <div className={`text-lg ${getSimilarity() >= 80 ? 'text-emerald-700' : getSimilarity() >= 50 ? 'text-amber-700' : 'text-red-700'}`}>
                    {userAnswer || '(未作答)'}
                  </div>
                </div>
                <div className="flex items-center justify-center gap-2">
                  <CheckCircle className={`w-5 h-5 ${getSimilarity() >= 80 ? 'text-emerald-500' : 'text-amber-500'}`} />
                  <span className="font-bold text-lg">
                    匹配度: {getSimilarity()}%
                  </span>
                </div>
              </div>
            ) : (
              <div className="text-slate-400">
                点击播放按钮开始听写练习
              </div>
            )}
          </div>
          
          <div className="flex items-center justify-center gap-4 mb-6">
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={audioUrl ? handlePlayPause : undefined}
              className={`
                w-16 h-16 rounded-full flex items-center justify-center shadow-lg
                ${isPlaying 
                  ? 'bg-gradient-to-br from-red-400 to-red-500' 
                  : 'bg-gradient-to-br from-indigo-400 to-indigo-500'
                }
                ${!audioUrl ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
              `}
            >
              {isPlaying ? (
                <Pause className="w-8 h-8 text-white" />
              ) : (
                <Play className="w-8 h-8 text-white ml-1" />
              )}
            </motion.button>
            
            <Button 
              variant="outline" 
              onClick={handleReplay}
              disabled={!audioUrl}
              className="flex items-center gap-2"
            >
              <RotateCcw className="w-4 h-4" />
              重播
            </Button>
          </div>
          
          <div className="w-full bg-slate-200 rounded-full h-2 mb-8 overflow-hidden">
            <motion.div
              className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 rounded-full"
              initial={{ width: 0 }}
              animate={{ width: `${(currentTime / duration) * 100}%` }}
            />
          </div>
          
          <div className="mb-6">
            <label className="block text-sm font-medium text-slate-700 mb-2">
              请输入你听到的内容
            </label>
            <Input
              value={userAnswer}
              onChange={(e) => setUserAnswer(e.target.value)}
              placeholder="在这里输入..."
              disabled={isChecked}
              className="text-center"
            />
          </div>
          
          {!isChecked && (
            <Button onClick={handleCheck} disabled={!userAnswer.trim()}>
              提交答案
            </Button>
          )}
          
          {isChecked && (
            <Button 
              onClick={() => {
                setUserAnswer('');
                setIsChecked(false);
                setShowResult(false);
                setCurrentTime(0);
              }}
              variant="secondary"
            >
              再练一次
            </Button>
          )}
        </div>
        
        {audioUrl && (
          <audio 
            ref={audioRef}
            src={audioUrl}
            onTimeUpdate={(e) => setCurrentTime(e.currentTarget.currentTime)}
            onLoadedMetadata={(e) => setDuration(e.currentTarget.duration)}
            onEnded={() => setIsPlaying(false)}
          />
        )}
      </Card.Body>
    </Card>
  );
}
