import { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Mic, MicOff, Play, Pause, RotateCcw, Volume2 } from 'lucide-react';
import { Button, Card } from '../common';

interface SpeakingRecorderProps {
  targetText: string;
  targetLanguage: string;
}

export default function SpeakingRecorder({ targetText, targetLanguage }: SpeakingRecorderProps) {
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [duration, setDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      
      const chunks: BlobPart[] = [];
      mediaRecorderRef.current.ondataavailable = (e) => {
        chunks.push(e.data);
      };
      
      mediaRecorderRef.current.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        setRecordedBlob(blob);
        stream.getTracks().forEach(track => track.stop());
      };
      
      mediaRecorderRef.current.start();
      setIsRecording(true);
      setDuration(0);
      
      timerRef.current = setInterval(() => {
        setDuration(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error('Error accessing microphone:', err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    }
  };

  const playRecording = () => {
    if (recordedBlob && audioRef.current) {
      audioRef.current.play();
      setIsPlaying(true);
    }
  };

  const pausePlaying = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const resetRecording = () => {
    setRecordedBlob(null);
    setDuration(0);
    setIsPlaying(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.onended = () => setIsPlaying(false);
    }
  }, []);

  return (
    <Card className="max-w-2xl mx-auto">
      <Card.Body className="p-8 text-center">
        <div className="mb-8">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-50 rounded-full text-indigo-600 text-sm mb-4">
            <Volume2 className="w-4 h-4" />
            <span>{targetLanguage === 'en' ? 'English' : targetLanguage === 'ja' ? '日本語' : '한국어'}</span>
          </div>
          <h3 className="text-3xl font-bold text-slate-800 mb-2">
            请跟读以下内容
          </h3>
          <p className="text-xl text-indigo-600 font-medium">
            "{targetText}"
          </p>
        </div>
        
        <div className="relative w-40 h-40 mx-auto mb-8">
          <motion.div
            animate={isRecording ? { scale: [1, 1.1, 1] } : {}}
            transition={{ repeat: isRecording ? Infinity : 0, duration: 1 }}
            className={`
              absolute inset-0 rounded-full flex items-center justify-center
              ${isRecording 
                ? 'bg-gradient-to-br from-red-400 to-red-500 shadow-lg shadow-red-200' 
                : recordedBlob
                  ? 'bg-gradient-to-br from-emerald-400 to-emerald-500'
                  : 'bg-gradient-to-br from-indigo-400 to-indigo-500'
              }
            `}
          >
            <button
              onClick={isRecording ? stopRecording : recordedBlob ? resetRecording : startRecording}
              className="w-20 h-20 rounded-full bg-white/20 flex items-center justify-center"
            >
              {isRecording ? (
                <MicOff className="w-10 h-10 text-white" />
              ) : recordedBlob ? (
                <RotateCcw className="w-10 h-10 text-white" />
              ) : (
                <Mic className="w-10 h-10 text-white" />
              )}
            </button>
          </motion.div>
          
          {isRecording && (
            <>
              <div className="absolute -top-2 left-1/2 -translate-x-1/2 flex gap-1">
                {[...Array(5)].map((_, i) => (
                  <motion.div
                    key={i}
                    className="w-1 h-4 bg-red-400 rounded-full"
                    animate={{ height: [4, 16, 4] }}
                    transition={{ 
                      repeat: Infinity, 
                      duration: 0.5, 
                      delay: i * 0.1 
                    }}
                  />
                ))}
              </div>
            </>
          )}
        </div>
        
        {recordedBlob && (
          <audio ref={audioRef} src={URL.createObjectURL(recordedBlob)} />
        )}
        
        <div className="flex items-center justify-center gap-4 mb-6">
          {recordedBlob && !isPlaying && (
            <Button onClick={playRecording} variant="secondary" className="flex items-center gap-2">
              <Play className="w-4 h-4" />
              播放录音
            </Button>
          )}
          {isPlaying && (
            <Button onClick={pausePlaying} variant="outline" className="flex items-center gap-2">
              <Pause className="w-4 h-4" />
              暂停
            </Button>
          )}
        </div>
        
        <div className="text-slate-500">
          {isRecording ? (
            <span className="text-red-500 font-medium animate-pulse">
              录音中... {formatTime(duration)}
            </span>
          ) : recordedBlob ? (
            <span>录音时长: {formatTime(duration)}</span>
          ) : (
            <span>点击麦克风开始录音</span>
          )}
        </div>
        
        {!isRecording && !recordedBlob && (
          <div className="mt-6 p-4 bg-amber-50 rounded-xl border border-amber-200">
            <p className="text-sm text-amber-800">
              💡 提示：建议录音时间控制在 5-30 秒之间，可以多次尝试以获得最佳效果
            </p>
          </div>
        )}
      </Card.Body>
    </Card>
  );
}
