import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Bookmark, Share2, Send, X, Check } from 'lucide-react';
import { Card, Avatar, Badge, Button, Input } from '../common';
import { CommunityPost } from '../../data/types';

interface PostCardProps {
  post: CommunityPost;
}

export default function PostCard({ post }: PostCardProps) {
  const [liked, setLiked] = useState(false);
  const [likes, setLikes] = useState(post.likes);
  const [bookmarked, setBookmarked] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [commentText, setCommentText] = useState('');
  const [comments, setComments] = useState([
    { id: 1, username: '学习者A', content: '说得太好了！', time: '1小时前' },
    { id: 2, username: '日语爱好者', content: '我也在学习日语，一起加油！', time: '2小时前' },
  ]);

  const timeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);
    
    if (diffDays > 0) return `${diffDays}天前`;
    if (diffHours > 0) return `${diffHours}小时前`;
    if (diffMins > 0) return `${diffMins}分钟前`;
    return '刚刚';
  };

  const handleLike = () => {
    if (liked) {
      setLikes(likes - 1);
    } else {
      setLikes(likes + 1);
    }
    setLiked(!liked);
  };

  const handleSubmitComment = () => {
    if (commentText.trim()) {
      setComments([...comments, {
        id: Date.now(),
        username: '我',
        content: commentText,
        time: '刚刚',
      }]);
      setCommentText('');
    }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    setShowShare(false);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <Card>
        <Card.Body className="p-5">
          <div className="flex items-start gap-3 mb-4">
            <Avatar name={post.username} />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <span className="font-semibold text-slate-800">{post.username}</span>
                <span className="text-sm text-slate-400">·</span>
                <span className="text-sm text-slate-500">{timeAgo(post.createdAt)}</span>
              </div>
            </div>
          </div>
          
          <p className="text-slate-700 mb-4 leading-relaxed">
            {post.content}
          </p>
          
          <div className="flex flex-wrap gap-2 mb-4">
            <Badge variant="primary" size="sm">
              #{post.language === 'en' ? '英语' : post.language === 'ja' ? '日语' : '韩语'}
            </Badge>
          </div>
          
          <div className="flex items-center justify-between pt-3 border-t border-slate-100">
            <button 
              onClick={handleLike}
              className={`flex items-center gap-2 transition-colors group ${
                liked ? 'text-red-500' : 'text-slate-500 hover:text-red-500'
              }`}
            >
              <Heart className={`w-5 h-5 ${liked ? 'fill-red-500' : 'group-hover:fill-red-500'}`} />
              <span className="text-sm">{likes}</span>
            </button>
            
            <button 
              onClick={() => setShowComments(true)}
              className="flex items-center gap-2 text-slate-500 hover:text-indigo-500 transition-colors group"
            >
              <MessageCircle className="w-5 h-5" />
              <span className="text-sm">{comments.length}</span>
            </button>
            
            <button 
              onClick={() => setBookmarked(!bookmarked)}
              className={`flex items-center gap-2 transition-colors ${
                bookmarked ? 'text-amber-500' : 'text-slate-500 hover:text-amber-500'
              }`}
            >
              <Bookmark className={`w-5 h-5 ${bookmarked ? 'fill-amber-500' : ''}`} />
            </button>
            
            <button 
              onClick={() => setShowShare(true)}
              className="flex items-center gap-2 text-slate-500 hover:text-indigo-500 transition-colors group"
            >
              <Share2 className="w-5 h-5" />
            </button>
          </div>
        </Card.Body>
      </Card>

      <AnimatePresence>
        {showComments && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
            onClick={() => setShowComments(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-2xl w-full max-w-lg max-h-[80vh] overflow-hidden"
            >
              <div className="flex items-center justify-between p-6 border-b">
                <h2 className="text-xl font-bold text-slate-800">评论 ({comments.length})</h2>
                <button
                  onClick={() => setShowComments(false)}
                  className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
                >
                  <X className="w-5 h-5 text-slate-500" />
                </button>
              </div>
              
              <div className="p-6 overflow-y-auto max-h-[50vh] space-y-4">
                {comments.map((comment) => (
                  <div key={comment.id} className="flex gap-3">
                    <Avatar name={comment.username} size="sm" />
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium text-slate-800 text-sm">{comment.username}</span>
                        <span className="text-xs text-slate-400">{comment.time}</span>
                      </div>
                      <p className="text-slate-700 text-sm">{comment.content}</p>
                    </div>
                  </div>
                ))}
              </div>
              
              <div className="p-4 border-t">
                <div className="flex gap-3">
                  <Input
                    placeholder="写下你的评论..."
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleSubmitComment()}
                  />
                  <Button size="sm" onClick={handleSubmitComment}>
                    <Send className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showShare && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
            onClick={() => setShowShare(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-2xl w-full max-w-sm p-6"
            >
              <h3 className="text-lg font-bold text-slate-800 mb-4">分享帖子</h3>
              <div className="space-y-3">
                <button
                  onClick={handleShare}
                  className="w-full flex items-center gap-3 p-3 bg-slate-50 rounded-lg hover:bg-slate-100 transition-colors"
                >
                  <Share2 className="w-5 h-5 text-indigo-500" />
                  <span className="text-slate-700">复制链接</span>
                </button>
                <button className="w-full flex items-center gap-3 p-3 bg-slate-50 rounded-lg hover:bg-slate-100 transition-colors">
                  <MessageCircle className="w-5 h-5 text-green-500" />
                  <span className="text-slate-700">分享到微信</span>
                </button>
                <button className="w-full flex items-center gap-3 p-3 bg-slate-50 rounded-lg hover:bg-slate-100 transition-colors">
                  <MessageCircle className="w-5 h-5 text-blue-500" />
                  <span className="text-slate-700">分享到QQ</span>
                </button>
              </div>
              <button
                onClick={() => setShowShare(false)}
                className="w-full mt-4 py-2 text-slate-500 hover:text-slate-700 transition-colors"
              >
                取消
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
