import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Mic, ChevronLeft, ChevronRight } from 'lucide-react';
import { Navbar } from './Navbar';
import { SpeakingRecorder } from '../components/practice';

const speakingTexts = [
  { id: 1, language: 'en', text: 'Hello, how are you today?' },
  { id: 2, language: 'en', text: 'I am learning a new language.' },
  { id: 3, language: 'ja', text: '今日はいい天気ですね。' },
  { id: 4, language: 'ja', text: '日本語を勉強しています。' },
  { id: 5, language: 'ko', text: '안녕하세요, 만나서 반갑습니다.' },
  { id: 6, language: 'ko', text: '한국어를 배우고 있어요.' },
];

export function SpeakingPage() {
  const navigate = useNavigate();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [recordings, setRecordings] = useState<number[]>([]);

  const currentText = speakingTexts[currentIndex];

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleNext = () => {
    if (currentIndex < speakingTexts.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const handleRecordingComplete = () => {
    if (!recordings.includes(currentText.id)) {
      setRecordings([...recordings, currentText.id]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => navigate('/practice')}
            className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-6 h-6 text-slate-600" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-pink-400 to-rose-500 rounded-xl flex items-center justify-center">
              <Mic className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800">口语跟读</h1>
              <p className="text-sm text-slate-500">练习发音，提升口语流利度</p>
            </div>
          </div>
        </div>
        
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={handlePrev}
            disabled={currentIndex === 0}
            className="p-2 hover:bg-slate-100 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="w-6 h-6 text-slate-600" />
          </button>
          
          <div className="text-sm text-slate-500">
            {currentIndex + 1} / {speakingTexts.length}
          </div>
          
          <button
            onClick={handleNext}
            disabled={currentIndex === speakingTexts.length - 1}
            className="p-2 hover:bg-slate-100 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronRight className="w-6 h-6 text-slate-600" />
          </button>
        </div>
        
        <SpeakingRecorder
          key={currentText.id}
          targetText={currentText.text}
          targetLanguage={currentText.language}
        />
        
        <div className="mt-8">
          <div className="flex items-center justify-between text-sm text-slate-500 mb-4">
            <span>练习进度</span>
            <span>{recordings.length} / {speakingTexts.length} 已完成</span>
          </div>
          <div className="w-full bg-slate-200 rounded-full h-2">
            <div
              className="h-full bg-gradient-to-r from-pink-500 to-rose-500 rounded-full transition-all duration-300"
              style={{ width: `${(recordings.length / speakingTexts.length) * 100}%` }}
            />
          </div>
        </div>
        
        <div className="mt-8 flex flex-wrap gap-2 justify-center">
          {speakingTexts.map((text, index) => (
            <button
              key={text.id}
              onClick={() => setCurrentIndex(index)}
              className={`
                w-10 h-10 rounded-full flex items-center justify-center text-sm font-medium
                transition-all
                ${index === currentIndex 
                  ? 'bg-gradient-to-r from-pink-500 to-rose-500 text-white' 
                  : recordings.includes(text.id)
                    ? 'bg-emerald-100 text-emerald-700'
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }
              `}
            >
              {index + 1}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
