import { motion } from 'framer-motion';
import { Users, Clock, Star } from 'lucide-react';
import { Card, Badge } from '../common';
import { courses } from '../../data/mockData';

export function FeaturedCourses() {
  const levelLabels = {
    beginner: { text: '初级', variant: 'success' as const },
    intermediate: { text: '中级', variant: 'warning' as const },
    advanced: { text: '高级', variant: 'error' as const },
  };

  return (
    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
      {courses.slice(0, 6).map((course, index) => {
        const level = levelLabels[course.level];
        
        return (
          <motion.div
            key={course.id}
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: index * 0.1 }}
          >
            <Card hover>
              <div className="relative h-40 overflow-hidden">
                <img
                  src={course.coverImage}
                  alt={course.title}
                  className="w-full h-full object-cover"
                />
                <div className="absolute top-3 right-3">
                  <Badge variant={level.variant}>{level.text}</Badge>
                </div>
              </div>
              
              <Card.Body>
                <h3 className="text-lg font-bold text-slate-800 mb-2 line-clamp-2">
                  {course.title}
                </h3>
                <p className="text-slate-600 text-sm mb-4 line-clamp-2">
                  {course.description}
                </p>
                
                <div className="flex items-center justify-between text-sm text-slate-500">
                  <div className="flex items-center gap-1">
                    <Users className="w-4 h-4" />
                    <span>{course.studentsCount.toLocaleString()}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Clock className="w-4 h-4" />
                    <span>{course.duration}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Star className="w-4 h-4 text-amber-400 fill-amber-400" />
                    <span>{course.rating}</span>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </motion.div>
        );
      })}
    </div>
  );
}
