import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Pen } from 'lucide-react';
import { Navbar } from './Navbar';
import { GrammarQuiz } from '../components/practice';
import { Card } from '../components/common';
import { grammarExercises } from '../data/mockData';
import { useLearningStore } from '../store';

export function GrammarPage() {
  const navigate = useNavigate();
  const { currentLanguage } = useLearningStore();
  const [showResults, setShowResults] = useState(false);
  const [lastScore, setLastScore] = useState({ score: 0, total: 0 });

  const quizzes = grammarExercises[currentLanguage] || grammarExercises['en'];

  const handleComplete = (score: number, total: number) => {
    setLastScore({ score, total });
    setShowResults(true);
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => navigate('/practice')}
            className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-6 h-6 text-slate-600" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-purple-400 to-indigo-500 rounded-xl flex items-center justify-center">
              <Pen className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800">语法练习</h1>
              <p className="text-sm text-slate-500">测试你的语法知识</p>
            </div>
          </div>
        </div>
        
        {!showResults ? (
          <GrammarQuiz quizzes={quizzes} onComplete={handleComplete} />
        ) : (
          <Card className="p-8 text-center">
            <div className="mb-6">
              <div className="text-6xl mb-4">
                {lastScore.score >= lastScore.total * 0.8 ? '🌟' : lastScore.score >= lastScore.total * 0.6 ? '👍' : '💪'}
              </div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">
                {lastScore.score >= lastScore.total * 0.8 
                  ? '太棒了！' 
                  : lastScore.score >= lastScore.total * 0.6 
                    ? '做得不错！' 
                    : '继续加油！'}
              </h2>
              <p className="text-slate-600">
                你答对了 {lastScore.score} / {lastScore.total} 题
              </p>
            </div>
            
            <div className="flex gap-4 justify-center">
              <button
                onClick={() => setShowResults(false)}
                className="px-6 py-2 bg-gradient-to-r from-indigo-500 to-purple-500 text-white font-medium rounded-lg hover:from-indigo-600 hover:to-purple-600 transition-all"
              >
                再练一次
              </button>
              <button
                onClick={() => navigate('/practice')}
                className="px-6 py-2 border-2 border-slate-300 text-slate-600 font-medium rounded-lg hover:bg-slate-50 transition-all"
              >
                返回训练中心
              </button>
            </div>
          </Card>
        )}
      </div>
    </div>
  );
}
