import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Headphones, ChevronLeft, ChevronRight } from 'lucide-react';
import { Navbar } from './Navbar';
import { ListeningPlayer } from '../components/practice';

const listeningExercises = [
  { id: 1, text: 'The weather is beautiful today.', language: 'en' },
  { id: 2, text: 'I would like to order a cup of coffee.', language: 'en' },
  { id: 3, text: '明日の会議は九時に始まります。', language: 'ja' },
  { id: 4, text: 'ありがとうございます。', language: 'ja' },
  { id: 5, text: '안녕하세요, 오늘 날씨가 좋네요.', language: 'ko' },
  { id: 6, text: '커피 한 잔 주세요.', language: 'ko' },
];

export function ListeningPage() {
  const navigate = useNavigate();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [completed, setCompleted] = useState<number[]>([]);

  const currentExercise = listeningExercises[currentIndex];

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleNext = () => {
    if (currentIndex < listeningExercises.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const handleComplete = () => {
    if (!completed.includes(currentExercise.id)) {
      setCompleted([...completed, currentExercise.id]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => navigate('/practice')}
            className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-6 h-6 text-slate-600" />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-amber-400 to-orange-500 rounded-xl flex items-center justify-center">
              <Headphones className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800">听力训练</h1>
              <p className="text-sm text-slate-500">听写练习，提高听力理解</p>
            </div>
          </div>
        </div>
        
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={handlePrev}
            disabled={currentIndex === 0}
            className="p-2 hover:bg-slate-100 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="w-6 h-6 text-slate-600" />
          </button>
          
          <div className="text-sm text-slate-500">
            {currentIndex + 1} / {listeningExercises.length}
          </div>
          
          <button
            onClick={handleNext}
            disabled={currentIndex === listeningExercises.length - 1}
            className="p-2 hover:bg-slate-100 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronRight className="w-6 h-6 text-slate-600" />
          </button>
        </div>
        
        <ListeningPlayer
          key={currentExercise.id}
          audioText={currentExercise.text}
        />
        
        <div className="mt-8">
          <div className="flex items-center justify-between text-sm text-slate-500 mb-4">
            <span>练习进度</span>
            <span>{completed.length} / {listeningExercises.length} 已完成</span>
          </div>
          <div className="w-full bg-slate-200 rounded-full h-2">
            <div
              className="h-full bg-gradient-to-r from-amber-500 to-orange-500 rounded-full transition-all duration-300"
              style={{ width: `${(completed.length / listeningExercises.length) * 100}%` }}
            />
          </div>
        </div>
        
        <div className="mt-8 flex flex-wrap gap-2 justify-center">
          {listeningExercises.map((exercise, index) => (
            <button
              key={exercise.id}
              onClick={() => setCurrentIndex(index)}
              className={`
                w-10 h-10 rounded-full flex items-center justify-center text-sm font-medium
                transition-all
                ${index === currentIndex 
                  ? 'bg-gradient-to-r from-amber-500 to-orange-500 text-white' 
                  : completed.includes(exercise.id)
                    ? 'bg-emerald-100 text-emerald-700'
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }
              `}
            >
              {index + 1}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
