import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Volume2, RotateCcw, Check, X } from 'lucide-react';
import { Button } from '../common';
import { FlashCard as FlashCardType } from '../../data/types';

interface FlashCardProps {
  cards: FlashCardType[];
  currentIndex: number;
  onNext: () => void;
  onPrev: () => void;
  onKnow: () => void;
  onDontKnow: () => void;
}

export default function FlashCard({ 
  cards, 
  currentIndex, 
  onNext, 
  onPrev, 
  onKnow, 
  onDontKnow 
}: FlashCardProps) {
  const [isFlipped, setIsFlipped] = useState(false);
  const card = cards[currentIndex];

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const handleNext = () => {
    setIsFlipped(false);
    onNext();
  };

  const handlePrev = () => {
    setIsFlipped(false);
    onPrev();
  };

  return (
    <div className="flex flex-col items-center">
      <div className="text-sm text-slate-500 mb-4">
        {currentIndex + 1} / {cards.length}
      </div>
      
      <div 
        className="relative w-full max-w-md h-80 cursor-pointer perspective-1000"
        onClick={handleFlip}
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={currentIndex}
            className="absolute inset-0 w-full h-full"
            initial={{ rotateY: -90, opacity: 0 }}
            animate={{ rotateY: 0, opacity: 1 }}
            exit={{ rotateY: 90, opacity: 0 }}
            transition={{ duration: 0.5 }}
            style={{ transformStyle: 'preserve-3d' }}
          >
            <div
              className={`
                absolute inset-0 w-full h-full rounded-2xl p-8
                flex flex-col items-center justify-center
                backface-hidden shadow-xl
                ${isFlipped 
                  ? 'bg-gradient-to-br from-emerald-500 to-emerald-600 text-white' 
                  : 'bg-white border-2 border-slate-200'
                }
              `}
              style={{ backfaceVisibility: 'hidden' }}
            >
              {isFlipped ? (
                <div className="text-center">
                  <div className="text-4xl font-bold mb-4">{card.back}</div>
                  {card.example && (
                    <div className="text-sm opacity-80 italic">
                      {card.example}
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-center">
                  <div className="text-5xl font-bold text-slate-800 mb-3">
                    {card.front}
                  </div>
                  {card.pronunciation && (
                    <div className="text-lg text-slate-500 mb-4">
                      {card.pronunciation}
                    </div>
                  )}
                  <Volume2 className="w-8 h-8 text-slate-400 mx-auto" />
                </div>
              )}
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
      
      <div className="mt-6 flex items-center gap-4">
        <Button 
          variant="outline" 
          onClick={handlePrev}
          disabled={currentIndex === 0}
          className="flex items-center gap-2"
        >
          <RotateCcw className="w-4 h-4" />
          上一张
        </Button>
        
        <div className="flex gap-3">
          <Button 
            variant="primary" 
            onClick={() => { onKnow(); handleNext(); }}
            className="bg-emerald-500 hover:bg-emerald-600"
          >
            <Check className="w-5 h-5 mr-2" />
            认识
          </Button>
          <Button 
            variant="outline" 
            onClick={() => { onDontKnow(); handleNext(); }}
            className="border-red-300 text-red-500 hover:bg-red-50"
          >
            <X className="w-5 h-5 mr-2" />
            不认识
          </Button>
        </div>
        
        <Button 
          variant="outline" 
          onClick={handleNext}
          disabled={currentIndex === cards.length - 1}
        >
          下一张
        </Button>
      </div>
      
      <p className="mt-4 text-sm text-slate-500">
        点击卡片翻转查看答案
      </p>
    </div>
  );
}
