import { HashRouter as Router, Routes, Route } from "react-router-dom";
import { HomePage, LearningPage, CourseDetailPage, LessonDetailPage, PracticePage, FlashcardPage, GrammarPage, SpeakingPage, ListeningPage, CommunityPage, ProfilePage, LoginPage, RegisterPage } from "./pages";

export default function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
        <Route path="/learn" element={<LearningPage />} />
        <Route path="/course/:id" element={<CourseDetailPage />} />
        <Route path="/lesson/:courseId/:lessonId" element={<LessonDetailPage />} />
        <Route path="/practice" element={<PracticePage />} />
        <Route path="/practice/flashcards" element={<FlashcardPage />} />
        <Route path="/practice/grammar" element={<GrammarPage />} />
        <Route path="/practice/speaking" element={<SpeakingPage />} />
        <Route path="/practice/listening" element={<ListeningPage />} />
        <Route path="/community" element={<CommunityPage />} />
        <Route path="/profile" element={<ProfilePage />} />
      </Routes>
    </Router>
  );
}
