import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Clock, Users, Star, Play, BookOpen, FileText, Mic, Headphones, CheckCircle } from 'lucide-react';
import { Navbar } from './Navbar';
import { LearningPath } from '../components/learning';
import { Card, Button, Badge, ProgressBar } from '../components/common';
import { courses } from '../data/mockData';
import { useLearningStore } from '../store';

export function CourseDetailPage() {
  const { id: courseId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { progress } = useLearningStore();
  
  const course = courses.find(c => c.id === courseId);
  const courseProgress = progress.find(p => p.courseId === courseId);

  if (!course) {
    return (
      <div className="min-h-screen bg-slate-50">
        <Navbar />
        <div className="max-w-4xl mx-auto px-4 py-12 text-center">
          <h1 className="text-2xl font-bold text-slate-800 mb-4">课程未找到</h1>
          <p className="text-slate-600 mb-6">抱歉，您访问的课程不存在</p>
          <Button onClick={() => navigate('/learn')}>返回学习中心</Button>
        </div>
      </div>
    );
  }

  const completedLessons = courseProgress?.completedLessons || [];
  const completionRate = course.lessons.length > 0 
    ? Math.round((completedLessons.length / course.lessons.length) * 100) 
    : 0;

  const levelLabels = {
    beginner: { text: '初级', color: 'bg-emerald-100 text-emerald-700' },
    intermediate: { text: '中级', color: 'bg-amber-100 text-amber-700' },
    advanced: { text: '高级', color: 'bg-red-100 text-red-700' },
  };

  const level = levelLabels[course.level];

  const lessonTypeIcons: Record<string, any> = {
    vocabulary: BookOpen,
    grammar: FileText,
    speaking: Mic,
    listening: Headphones,
  };

  const lessonTypeLabels: Record<string, string> = {
    vocabulary: '词汇',
    grammar: '语法',
    speaking: '口语',
    listening: '听力',
  };

  const handleLessonClick = (lessonId: string) => {
    navigate(`/lesson/${courseId}/${lessonId}`);
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <button
          onClick={() => navigate('/learn')}
          className="flex items-center gap-2 text-slate-600 hover:text-indigo-600 transition-colors mb-6"
        >
          <ArrowLeft className="w-5 h-5" />
          <span>返回学习中心</span>
        </button>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <div className="relative h-64 rounded-2xl overflow-hidden mb-8">
            <img
              src={course.coverImage}
              alt={course.title}
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/30 to-transparent" />
            <div className="absolute bottom-0 left-0 right-0 p-8">
              <div className="flex items-center gap-3 mb-3">
                <span className={`px-3 py-1 text-sm font-medium rounded-full ${level.color}`}>
                  {level.text}
                </span>
                <span className="text-white/80 text-sm">
                  {course.language === 'en' ? '🇬🇧 英语' : course.language === 'ja' ? '🇯🇵 日语' : '🇰🇷 韩语'}
                </span>
              </div>
              <h1 className="text-3xl font-bold text-white mb-3">{course.title}</h1>
              <p className="text-white/90 text-lg max-w-2xl">{course.description}</p>
            </div>
          </div>
          
          <div className="grid lg:grid-cols-3 gap-6 mb-8">
            <Card className="p-6 text-center">
              <div className="flex items-center justify-center gap-2 text-slate-600 mb-2">
                <Clock className="w-5 h-5" />
                <span className="font-medium">课程时长</span>
              </div>
              <div className="text-2xl font-bold text-slate-800">{course.duration}</div>
            </Card>
            
            <Card className="p-6 text-center">
              <div className="flex items-center justify-center gap-2 text-slate-600 mb-2">
                <Users className="w-5 h-5" />
                <span className="font-medium">学习人数</span>
              </div>
              <div className="text-2xl font-bold text-slate-800">{course.studentsCount.toLocaleString()}</div>
            </Card>
            
            <Card className="p-6 text-center">
              <div className="flex items-center justify-center gap-2 text-slate-600 mb-2">
                <Star className="w-5 h-5" />
                <span className="font-medium">课程评分</span>
              </div>
              <div className="text-2xl font-bold text-slate-800">4.9</div>
            </Card>
          </div>
          
          <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2">
              <Card className="p-6 mb-6">
                <h2 className="text-xl font-bold text-slate-800 mb-4">课程进度</h2>
                <div className="mb-4">
                  <div className="flex justify-between text-sm mb-2">
                    <span className="text-slate-600">已完成</span>
                    <span className="font-medium text-indigo-600">{completionRate}%</span>
                  </div>
                  <ProgressBar value={completionRate} size="lg" />
                </div>
                <div className="text-sm text-slate-500">
                  已完成 {completedLessons.length} / {course.lessons.length} 个课时
                </div>
              </Card>
              
              <Card className="p-6">
                <h2 className="text-xl font-bold text-slate-800 mb-6">课程内容</h2>
                <LearningPath 
                  lessons={course.lessons.map(l => ({
                    id: l.id,
                    title: l.title,
                    completed: completedLessons.includes(l.id),
                  }))}
                  onLessonClick={handleLessonClick}
                />
              </Card>
            </div>
            
            <div className="space-y-6">
              <Card className="p-6">
                <h3 className="font-semibold text-slate-800 mb-4">课程介绍</h3>
                <p className="text-slate-600 text-sm mb-6 leading-relaxed">
                  {course.description}
                  本课程将帮助你系统地学习{course.language === 'en' ? '英语' : course.language === 'ja' ? '日语' : '韩语'}，
                  从基础词汇到进阶语法，全方位提升你的语言能力。
                </p>
                <Button 
                  className="w-full flex items-center justify-center gap-2"
                  onClick={() => {
                    const nextLesson = course.lessons.find(l => !completedLessons.includes(l.id));
                    if (nextLesson) {
                      handleLessonClick(nextLesson.id);
                    }
                  }}
                >
                  <Play className="w-5 h-5" />
                  {completionRate > 0 ? '继续学习' : '开始学习'}
                </Button>
              </Card>
              
              <Card className="p-6">
                <h3 className="font-semibold text-slate-800 mb-4">课时列表</h3>
                <div className="space-y-3">
                  {course.lessons.map((lesson, index) => {
                    const TypeIcon = lessonTypeIcons[lesson.type] || BookOpen;
                    const isCompleted = completedLessons.includes(lesson.id);
                    
                    return (
                      <div
                        key={lesson.id}
                        className={`
                          p-3 rounded-lg transition-all cursor-pointer
                          ${isCompleted 
                            ? 'bg-emerald-50 border border-emerald-200' 
                            : 'bg-slate-50 hover:bg-slate-100'
                          }
                        `}
                        onClick={() => handleLessonClick(lesson.id)}
                      >
                        <div className="flex items-center gap-3">
                          <div className={`
                            w-8 h-8 rounded-full flex items-center justify-center
                            ${isCompleted ? 'bg-emerald-500' : 'bg-indigo-500'}
                          `}>
                            {isCompleted ? (
                              <CheckCircle className="w-4 h-4 text-white" />
                            ) : (
                              <TypeIcon className="w-4 h-4 text-white" />
                            )}
                          </div>
                          <div className="flex-1">
                            <div className="text-sm font-medium text-slate-800">
                              {index + 1}. {lesson.title}
                            </div>
                            <div className="flex items-center gap-3 text-xs text-slate-500">
                              <span className="flex items-center gap-1">
                                <TypeIcon className="w-3 h-3" />
                                {lessonTypeLabels[lesson.type]}
                              </span>
                              <span>{lesson.duration}分钟</span>
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </Card>
              
              <Card className="p-6 bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-0">
                <h3 className="font-semibold mb-2">💡 学习小贴士</h3>
                <p className="text-sm text-white/90">
                  建议每天坚持学习30分钟，保持学习的连续性，这样效果会更好哦！
                </p>
              </Card>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}
