import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle, XCircle, ChevronRight, Lightbulb } from 'lucide-react';
import { Button, Card } from '../common';
import { GrammarQuiz as GrammarQuizType } from '../../data/types';

interface GrammarQuizProps {
  quizzes: GrammarQuizType[];
  onComplete: (score: number, total: number) => void;
}

export default function GrammarQuiz({ quizzes, onComplete }: GrammarQuizProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [isCompleted, setIsCompleted] = useState(false);

  const quiz = quizzes[currentIndex];

  const handleSelectAnswer = (index: number) => {
    if (isAnswered) return;
    setSelectedAnswer(index);
  };

  const handleSubmit = () => {
    if (selectedAnswer === null) return;
    setIsAnswered(true);
    
    if (selectedAnswer === quiz.correctAnswer) {
      setScore(prev => prev + 1);
    }
  };

  const handleNext = () => {
    if (currentIndex < quizzes.length - 1) {
      setCurrentIndex(prev => prev + 1);
      setSelectedAnswer(null);
      setIsAnswered(false);
    } else {
      setIsCompleted(true);
      onComplete(score + (selectedAnswer === quiz.correctAnswer ? 1 : 0), quizzes.length);
    }
  };

  if (isCompleted) {
    const percentage = Math.round((score / quizzes.length) * 100);
    return (
      <Card className="max-w-2xl mx-auto p-8 text-center">
        <motion.div
          initial={{ scale: 0 }}
          animate={{ scale: 1 }}
          className="mb-6"
        >
          <div className={`
            w-24 h-24 mx-auto rounded-full flex items-center justify-center
            ${percentage >= 80 ? 'bg-emerald-100' : percentage >= 60 ? 'bg-amber-100' : 'bg-red-100'}
          `}>
            <span className={`
              text-4xl font-bold
              ${percentage >= 80 ? 'text-emerald-600' : percentage >= 60 ? 'text-amber-600' : 'text-red-600'}
            `}>
              {percentage}%
            </span>
          </div>
        </motion.div>
        
        <h3 className="text-2xl font-bold text-slate-800 mb-2">
          {percentage >= 80 ? '太棒了！' : percentage >= 60 ? '做得不错！' : '继续加油！'}
        </h3>
        <p className="text-slate-600 mb-6">
          你答对了 {score} / {quizzes.length} 题
        </p>
        
        <div className="flex gap-4 justify-center">
          <Button onClick={() => {
            setCurrentIndex(0);
            setScore(0);
            setSelectedAnswer(null);
            setIsAnswered(false);
            setIsCompleted(false);
          }}>
            重新挑战
          </Button>
        </div>
      </Card>
    );
  }

  return (
    <Card className="max-w-2xl mx-auto">
      <Card.Header>
        <div className="flex items-center justify-between">
          <span className="text-sm text-slate-500">
            题目 {currentIndex + 1} / {quizzes.length}
          </span>
          <span className="text-sm font-medium text-indigo-600">
            得分: {score}
          </span>
        </div>
      </Card.Header>
      
      <Card.Body className="p-6">
        <h3 className="text-xl font-semibold text-slate-800 mb-6">
          {quiz.question}
        </h3>
        
        <div className="space-y-3">
          {quiz.options.map((option, index) => {
            const isSelected = selectedAnswer === index;
            const isCorrect = index === quiz.correctAnswer;
            
            return (
              <motion.div
                key={index}
                whileHover={{ scale: isAnswered ? 1 : 1.01 }}
                whileTap={{ scale: isAnswered ? 1 : 0.99 }}
                onClick={() => handleSelectAnswer(index)}
                className={`
                  p-4 rounded-xl border-2 cursor-pointer transition-all
                  ${isAnswered
                    ? isCorrect
                      ? 'border-emerald-500 bg-emerald-50'
                      : isSelected
                        ? 'border-red-500 bg-red-50'
                        : 'border-slate-200 bg-slate-50'
                    : isSelected
                      ? 'border-indigo-500 bg-indigo-50'
                      : 'border-slate-200 hover:border-indigo-300'
                  }
                `}
              >
                <div className="flex items-center gap-3">
                  <div className={`
                    w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium
                    ${isAnswered
                      ? isCorrect
                        ? 'bg-emerald-500 text-white'
                        : isSelected
                          ? 'bg-red-500 text-white'
                          : 'bg-slate-200 text-slate-600'
                      : isSelected
                        ? 'bg-indigo-500 text-white'
                        : 'bg-slate-200 text-slate-600'
                    }
                  `}>
                    {String.fromCharCode(65 + index)}
                  </div>
                  <span className="flex-1 text-slate-700">{option}</span>
                  {isAnswered && isCorrect && (
                    <CheckCircle className="w-5 h-5 text-emerald-500" />
                  )}
                  {isAnswered && isSelected && !isCorrect && (
                    <XCircle className="w-5 h-5 text-red-500" />
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>
        
        <AnimatePresence>
          {isAnswered && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="mt-6 p-4 bg-amber-50 rounded-xl border border-amber-200"
            >
              <div className="flex gap-3">
                <Lightbulb className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" />
                <div>
                  <div className="font-medium text-amber-800 mb-1">解析</div>
                  <div className="text-amber-700 text-sm">{quiz.explanation}</div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </Card.Body>
      
      <Card.Footer className="flex justify-end">
        {!isAnswered ? (
          <Button onClick={handleSubmit} disabled={selectedAnswer === null}>
            提交答案
          </Button>
        ) : (
          <Button onClick={handleNext} className="flex items-center gap-2">
            {currentIndex < quizzes.length - 1 ? (
              <>
                下一题
                <ChevronRight className="w-4 h-4" />
              </>
            ) : (
              '查看结果'
            )}
          </Button>
        )}
      </Card.Footer>
    </Card>
  );
}
