import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { User, LearningProgress } from '../data/types';

interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<boolean>;
  register: (email: string, username: string, password: string) => Promise<boolean>;
  logout: () => void;
  updateProfile: (data: Partial<User>) => void;
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      user: null,
      isAuthenticated: false,
      login: async (email: string, password: string) => {
        await new Promise(resolve => setTimeout(resolve, 500));
        const mockUser: User = {
          id: 'user-' + Date.now(),
          email,
          username: email.split('@')[0],
          nativeLanguage: 'zh',
          learningLanguages: ['en', 'ja', 'ko'],
          level: { en: 'beginner', ja: 'beginner', ko: 'beginner' },
          streak: 1,
          totalMinutes: 0,
          achievements: [],
          createdAt: new Date().toISOString(),
        };
        set({ user: mockUser, isAuthenticated: true });
        return true;
      },
      register: async (email: string, username: string, password: string) => {
        await new Promise(resolve => setTimeout(resolve, 500));
        const newUser: User = {
          id: 'user-' + Date.now(),
          email,
          username,
          nativeLanguage: 'zh',
          learningLanguages: [],
          level: {},
          streak: 0,
          totalMinutes: 0,
          achievements: [],
          createdAt: new Date().toISOString(),
        };
        set({ user: newUser, isAuthenticated: true });
        return true;
      },
      logout: () => {
        set({ user: null, isAuthenticated: false });
      },
      updateProfile: (data) => {
        const currentUser = get().user;
        if (currentUser) {
          set({ user: { ...currentUser, ...data } });
        }
      },
    }),
    {
      name: 'linguaflow-auth',
    }
  )
);

interface LearningState {
  currentLanguage: string;
  currentCourseId: string | null;
  progress: LearningProgress[];
  flashcardIndex: number;
  quizScore: number;
  setLanguage: (lang: string) => void;
  setCurrentCourse: (courseId: string | null) => void;
  completeLesson: (courseId: string, lessonId: string, score?: number) => void;
  updateFlashcardIndex: (index: number) => void;
  nextFlashcard: () => void;
  resetFlashcards: () => void;
  addQuizScore: (score: number) => void;
  resetQuizScore: () => void;
}

export const useLearningStore = create<LearningState>()(
  persist(
    (set, get) => ({
      currentLanguage: 'en',
      currentCourseId: null,
      progress: [],
      flashcardIndex: 0,
      quizScore: 0,
      setLanguage: (lang) => set({ currentLanguage: lang }),
      setCurrentCourse: (courseId) => set({ currentCourseId: courseId }),
      completeLesson: (courseId, lessonId, score) => {
        const currentProgress = get().progress;
        const courseProgress = currentProgress.find(p => p.courseId === courseId);
        if (courseProgress) {
          if (!courseProgress.completedLessons.includes(lessonId)) {
            courseProgress.completedLessons.push(lessonId);
          }
          if (score !== undefined) {
            courseProgress.quizScores[lessonId] = score;
          }
          set({ progress: [...currentProgress] });
        } else {
          set({
            progress: [...currentProgress, {
              userId: 'current',
              courseId,
              completedLessons: [lessonId],
              quizScores: score ? { [lessonId]: score } : {},
              lastStudyDate: new Date().toISOString(),
              totalTimeSpent: 0,
            }]
          });
        }
      },
      updateFlashcardIndex: (index) => set({ flashcardIndex: index }),
      nextFlashcard: () => {
        const current = get().flashcardIndex;
        set({ flashcardIndex: current + 1 });
      },
      resetFlashcards: () => set({ flashcardIndex: 0 }),
      addQuizScore: (score) => {
        const current = get().quizScore;
        set({ quizScore: current + score });
      },
      resetQuizScore: () => set({ quizScore: 0 }),
    }),
    {
      name: 'linguaflow-learning',
    }
  )
);
