import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Users, MessageSquare, TrendingUp, Calendar, X, Send, Image, Smile } from 'lucide-react';
import { Navbar } from './Navbar';
import { PostList } from '../components/community';
import { Card, Button, Input } from '../components/common';
import { communityPosts as initialPosts } from '../data/mockData';
import { useAuthStore } from '../store';

export function CommunityPage() {
  const { user } = useAuthStore();
  const [activeTab, setActiveTab] = useState<'posts' | 'groups'>('posts');
  const [showPostModal, setShowPostModal] = useState(false);
  const [postContent, setPostContent] = useState('');
  const [posts, setPosts] = useState(initialPosts);
  const [selectedLanguage, setSelectedLanguage] = useState('en');

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-8"
        >
          <h1 className="text-3xl font-bold text-slate-800 mb-2">学习社区</h1>
          <p className="text-slate-600">与志同道合的学习者一起交流进步</p>
        </motion.div>
        
        <div className="grid lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2">
            <div className="flex gap-4 mb-6">
              <button
                onClick={() => setActiveTab('posts')}
                className={`
                  px-4 py-2 rounded-lg font-medium transition-all flex items-center gap-2
                  ${activeTab === 'posts' 
                    ? 'bg-indigo-100 text-indigo-700' 
                    : 'text-slate-600 hover:bg-slate-100'
                  }
                `}
              >
                <MessageSquare className="w-4 h-4" />
                帖子
              </button>
              <button
                onClick={() => setActiveTab('groups')}
                className={`
                  px-4 py-2 rounded-lg font-medium transition-all flex items-center gap-2
                  ${activeTab === 'groups' 
                    ? 'bg-indigo-100 text-indigo-700' 
                    : 'text-slate-600 hover:bg-slate-100'
                  }
                `}
              >
                <Users className="w-4 h-4" />
                学习小组
              </button>
            </div>
            
            {activeTab === 'posts' ? (
              <PostList posts={posts} onNewPost={() => setShowPostModal(true)} />
            ) : (
              <div className="grid md:grid-cols-2 gap-4">
                {[
                  { name: '英语口语交流群', members: 1234, posts: 89 },
                  { name: '日语N3备考小组', members: 856, posts: 156 },
                  { name: '韩语TOPIK冲刺', members: 672, posts: 234 },
                  { name: '背单词打卡群', members: 2341, posts: 567 },
                ].map((group, index) => (
                  <motion.div
                    key={group.name}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.1 }}
                  >
                    <Card hover className="p-5">
                      <div className="flex items-start gap-3">
                        <div className="w-12 h-12 bg-gradient-to-br from-indigo-400 to-purple-500 rounded-xl flex items-center justify-center">
                          <Users className="w-6 h-6 text-white" />
                        </div>
                        <div className="flex-1">
                          <h3 className="font-semibold text-slate-800 mb-1">{group.name}</h3>
                          <div className="flex gap-4 text-sm text-slate-500">
                            <span>{group.members} 成员</span>
                            <span>{group.posts} 帖子</span>
                          </div>
                        </div>
                      </div>
                      <Button size="sm" className="w-full mt-4">
                        加入小组
                      </Button>
                    </Card>
                  </motion.div>
                ))}
              </div>
            )}
          </div>
          
          <div className="space-y-6">
            <Card>
              <Card.Body className="p-5">
                <h3 className="font-semibold text-slate-800 mb-4 flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-indigo-500" />
                  热门话题
                </h3>
                <div className="space-y-3">
                  {[
                    { tag: '日语N3备考', posts: 234 },
                    { tag: '英语口语练习', posts: 189 },
                    { tag: '韩语TOPIK', posts: 156 },
                    { tag: '学习方法分享', posts: 123 },
                    { tag: '每日打卡', posts: 98 },
                  ].map((topic) => (
                    <div key={topic.tag} className="flex items-center justify-between">
                      <span className="text-sm text-slate-700 hover:text-indigo-600 cursor-pointer">
                        #{topic.tag}
                      </span>
                      <span className="text-xs text-slate-400">{topic.posts}</span>
                    </div>
                  ))}
                </div>
              </Card.Body>
            </Card>
            
            <Card>
              <Card.Body className="p-5">
                <h3 className="font-semibold text-slate-800 mb-4 flex items-center gap-2">
                  <Calendar className="w-5 h-5 text-emerald-500" />
                  学习活动
                </h3>
                <div className="space-y-4">
                  {[
                    { title: '日语N3模拟考试', date: '本周六 14:00', participants: 45 },
                    { title: '英语口语角', date: '本周日 20:00', participants: 32 },
                    { title: '韩语发音训练营', date: '下周一 19:00', participants: 58 },
                  ].map((event) => (
                    <div key={event.title} className="p-3 bg-slate-50 rounded-lg">
                      <div className="font-medium text-slate-800 text-sm mb-1">{event.title}</div>
                      <div className="text-xs text-slate-500">{event.date} · {event.participants}人参与</div>
                    </div>
                  ))}
                </div>
              </Card.Body>
            </Card>
            
            {user && (
              <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-0">
                <Card.Body className="p-5">
                  <h3 className="font-semibold mb-2">分享你的学习心得</h3>
                  <p className="text-sm text-white/80 mb-4">
                    帮助他人，也可以获得积分奖励
                  </p>
                  <Button variant="outline" className="w-full border-white text-white hover:bg-white hover:text-indigo-600" onClick={() => setShowPostModal(true)}>
                    发布帖子
                  </Button>
                </Card.Body>
              </Card>
            )}
          </div>
        </div>
      </div>

      <AnimatePresence>
        {showPostModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
            onClick={() => setShowPostModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-2xl w-full max-w-lg"
            >
              <div className="flex items-center justify-between p-6 border-b">
                <h2 className="text-xl font-bold text-slate-800">发布帖子</h2>
                <button
                  onClick={() => setShowPostModal(false)}
                  className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
                >
                  <X className="w-5 h-5 text-slate-500" />
                </button>
              </div>
              
              <div className="p-6">
                <div className="flex gap-3 mb-4">
                  <div className="w-10 h-10 bg-gradient-to-br from-indigo-400 to-purple-500 rounded-full flex items-center justify-center text-white font-semibold">
                    {user?.username?.charAt(0)}
                  </div>
                  <div>
                    <div className="font-semibold text-slate-800">{user?.username}</div>
                    <div className="text-sm text-slate-500">分享你的学习心得</div>
                  </div>
                </div>
                
                <textarea
                  value={postContent}
                  onChange={(e) => setPostContent(e.target.value)}
                  placeholder="分享你的学习心得、经验或问题..."
                  className="w-full h-32 p-4 border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 outline-none resize-none"
                />
                
                <div className="flex items-center justify-between mt-4">
                  <div className="flex gap-2">
                    <button className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                      <Image className="w-5 h-5 text-slate-500" />
                    </button>
                    <button className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                      <Smile className="w-5 h-5 text-slate-500" />
                    </button>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <select
                      value={selectedLanguage}
                      onChange={(e) => setSelectedLanguage(e.target.value)}
                      className="px-3 py-2 border-2 border-slate-200 rounded-lg focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 outline-none"
                    >
                      <option value="en">英语</option>
                      <option value="ja">日语</option>
                      <option value="ko">韩语</option>
                    </select>
                  </div>
                </div>
              </div>
              
              <div className="p-6 border-t flex gap-3">
                <Button variant="outline" className="flex-1" onClick={() => setShowPostModal(false)}>
                  取消
                </Button>
                <Button className="flex-1 flex items-center justify-center gap-2" onClick={() => {
                  if (postContent.trim()) {
                    const newPost = {
                      id: 'post-' + Date.now(),
                      userId: user?.id || '',
                      username: user?.username || '用户',
                      avatar: '',
                      content: postContent,
                      likes: 0,
                      comments: 0,
                      createdAt: new Date().toISOString(),
                      language: selectedLanguage,
                    };
                    setPosts([newPost, ...posts]);
                    setPostContent('');
                    setShowPostModal(false);
                  }
                }}>
                  <Send className="w-4 h-4" />
                  发布
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
