import { motion } from 'framer-motion';

interface RadarChartProps {
  skills: {
    name: string;
    value: number;
    max: number;
  }[];
}

export default function RadarChart({ skills }: RadarChartProps) {
  const size = 200;
  const center = size / 2;
  const radius = 70;
  const angleStep = (2 * Math.PI) / skills.length;

  const getPoint = (value: number, index: number) => {
    const angle = index * angleStep - Math.PI / 2;
    const normalizedValue = value / 100;
    const x = center + radius * normalizedValue * Math.cos(angle);
    const y = center + radius * normalizedValue * Math.sin(angle);
    return { x, y };
  };

  const getLabelPoint = (index: number) => {
    const angle = index * angleStep - Math.PI / 2;
    const x = center + (radius + 30) * Math.cos(angle);
    const y = center + (radius + 30) * Math.sin(angle);
    return { x, y };
  };

  const getAxisPoint = (index: number) => {
    const angle = index * angleStep - Math.PI / 2;
    const x = center + radius * Math.cos(angle);
    const y = center + radius * Math.sin(angle);
    return { x, y };
  };

  const dataPoints = skills.map((skill, index) => getPoint(skill.value, index));
  const pathData = dataPoints.map((point, i) => `${i === 0 ? 'M' : 'L'} ${point.x} ${point.y}`).join(' ') + ' Z';

  return (
    <div className="relative">
      <svg width={size} height={size} className="mx-auto">
        {[0.25, 0.5, 0.75, 1].map((level, i) => (
          <motion.circle
            key={i}
            cx={center}
            cy={center}
            r={radius * level}
            fill="none"
            stroke="currentColor"
            strokeWidth="1"
            className="text-slate-200"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: i * 0.1 }}
          />
        ))}
        
        {skills.map((_, index) => {
          const point = getAxisPoint(index);
          return (
            <line
              key={index}
              x1={center}
              y1={center}
              x2={point.x}
              y2={point.y}
              stroke="currentColor"
              strokeWidth="1"
              className="text-slate-200"
            />
          );
        })}
        
        <motion.path
          d={pathData}
          fill="url(#radar-gradient)"
          fillOpacity="0.3"
          stroke="url(#radar-gradient)"
          strokeWidth="2"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{ duration: 1, ease: 'easeOut' }}
        />
        
        <defs>
          <linearGradient id="radar-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#4F46E5" />
            <stop offset="100%" stopColor="#A855F7" />
          </linearGradient>
        </defs>
        
        {dataPoints.map((point, index) => (
          <motion.circle
            key={index}
            cx={point.x}
            cy={point.y}
            r="4"
            fill="#4F46E5"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.5 + index * 0.1 }}
          />
        ))}
        
        {skills.map((skill, index) => {
          const labelPoint = getLabelPoint(index);
          return (
            <text
              key={index}
              x={labelPoint.x}
              y={labelPoint.y}
              textAnchor="middle"
              dominantBaseline="middle"
              className="text-xs fill-slate-600 font-medium"
            >
              {skill.name}
            </text>
          );
        })}
      </svg>
      
      <div className="mt-4 flex flex-wrap justify-center gap-4">
        {skills.map((skill, index) => (
          <div key={index} className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-gradient-to-r from-indigo-500 to-purple-500" />
            <span className="text-sm text-slate-600">{skill.name}: {skill.value}%</span>
          </div>
        ))}
      </div>
    </div>
  );
}
